import os
from dotenv import load_dotenv
import pandas as pd
from price_scraper import scrape_competitor_page, parse_competitor_price

load_dotenv()

# Load the catalog CSV generated by your first AI agent
df = pd.read_csv("../marketplace-sku-extractor/marketplace_new_skus.csv")

# Initialize new columns for competitor benchmarking
df["Market Price"] = None
df["In Stock"] = None
df["Margin Delta"] = None

print("🚀 Starting Competitor Benchmarking Pipeline...")

# Mapping the first catalog item to the live IndiaMART URL
competitor_urls = {
    "TurtleWax Pro": "https://www.indiamart.com/proddetail/turtle-wax-pro-t30-fine-car-polish-compound-1l-2850841938888.html"
}

print(df[["brand_name", "Minimum Retail Price"]].head())

USD_TO_INR = 87.0  # Or fetch dynamically

for index, row in df.iterrows():
    brand = str(row.get("brand_name", "")).strip()
    
    # Flexible matching for Turtle Wax
    if "turtle" in brand.lower():
        url = competitor_urls["TurtleWax Pro"]
        print(f"\nScraping market data for {brand}...")
        
        raw_html = scrape_competitor_page(url)
        if raw_html:
            market_data = parse_competitor_price(raw_html)
            
            # Clean and normalize internal price to INR
            internal_usd = float(str(row["Minimum Retail Price"]).replace('$', '').strip())
            internal_inr = round(internal_usd * USD_TO_INR, 2)
            
            df.at[index, "Market Price"] = f"{market_data.price} {market_data.currency}"
            df.at[index, "In Stock"] = market_data.in_stock
            df.at[index, "Margin Delta"] = round(market_data.price - internal_inr, 2)

print("\n💾 Exporting final marketplace analytics...")
df.to_csv("benchmarked_skus.csv", index=False)
print("✅ Complete. Check benchmarked_skus.csv in your explorer panel.")